 "content": "from collections import deque

# The output shows two 3x3 count cards: 3 for T pieces whose stem is
# above the bar, and 1 for those whose stem is below the bar.
_COUNT_CARDS = {
    0: (),
    1: ((0, 0),),
    2: ((0, 0), (2, 1)),
    3: ((0, 0), (0, 2), (2, 0)),
    4: ((0, 0), (0, 2), (2, 0), (2, 2)),
}

def transform(grid):
    h, w = len(grid), len(grid[0])
    unseen = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2}
    counts = {"stem_above": 0, "stem_below": 0}
    while unseen:
        start = unseen.pop()
        q = deque([start])
        comp = {start}
        while q:
            r, c = q.popleft()
            for p in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                if p in unseen:
                    unseen.remove(p)
                    comp.add(p)
                    q.append(p)
        if len(comp) != 4:
            continue
        minr = min(r for r, _ in comp)
        maxr = max(r for r, _ in comp)
        minc = min(c for _, c in comp)
        maxc = max(c for _, c in comp)
        if maxr - minr != 1 or maxc - minc != 2:
            continue
        norm = {(r-minr, c-minc) for r,c in comp}
        if norm == {(0,1),(1,0),(1,1),(1,2)}:
            counts["stem_above"] += 1
        elif norm == {(0,0),(0,1),(0,2),(1,1)}:
            counts["stem_below"] += 1
    out = [[0] * 6 for _ in range(3)]
    for side, (kind, color) in enumerate((("stem_above", 3), ("stem_below", 1))):
        for r, c in _COUNT_CARDS.get(counts[kind], ()):
            out[r][side * 3 + c] = color
    return out

if __name__ == '__main__':
    pass
",
 "cross_profile": false
}

